package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class RomanReadTest {
 @Test public void all100CanonicalPublicGivensAndLearnerGroups(){Set<String> signatures=new HashSet<>();for(int n=1;n<=100;n++){Question q=RomanRead.make(n);assertTrue(signatures.add(q.signature()));q.answers=new String[]{"poison"};q.expression="poison";assertEquals(Integer.valueOf(n),RomanRead.read(q));assertTrue(new Checker().check(q,List.of(),List.of(""+n)).correct());assertEquals(Checker.Status.WRONG_ANSWER,new Checker().check(q,List.of(),List.of(""+(n+1))).status);HelpPlan p=HelpPlan.forQuestion(q);assertFalse(p.canTransfer());assertTrue(p.restore(null,q.id).entries.stream().allMatch(String::isEmpty));String[] groups=RomanRead.groups(RomanRead.numeral(n));assertEquals(groups.length+1,p.size());int sum=0;for(int i=0;i<groups.length;i++){int part=independent(groups[i]);sum+=part;assertTrue(p.step(i).accepts(""+part));assertFalse(p.step(i).before.matches("(?s).*[0-9].*"));}assertEquals(n,sum);assertTrue(p.step(p.size()-1).accepts(""+n));assertTrue(q.choices.isEmpty());}assertEquals(100,signatures.size());assertEquals("IV",RomanRead.numeral(4));assertEquals("IX",RomanRead.numeral(9));assertEquals("XL",RomanRead.numeral(40));assertEquals("XC",RomanRead.numeral(90));assertEquals("C",RomanRead.numeral(100));}
 private static int independent(String s){int value=0,previous=0;for(int i=s.length()-1;i>=0;i--){int next=switch(s.charAt(i)){case 'I'->1;case 'V'->5;case 'X'->10;case 'L'->50;case 'C'->100;default->throw new AssertionError(s);};value+=next<previous?-next:next;previous=next;}return value;}
 @Test public void actual100FreshDrawsThenOldestAndGradeBoundary(){Generator g=new Generator(new Random(145));CurriculumLimits limits=GlobalCurriculum.limits("england-primary-2021-v1",RomanRead.ID,4);List<String> history=new ArrayList<>();for(int i=0;i<100;i++){Question q=g.next(RomanRead.ID,history,false,limits);assertNotNull(RomanRead.read(q));assertFalse(history.contains(q.signature()));history.add(q.signature());}assertEquals(history.get(0),g.next(RomanRead.ID,history,false,limits).signature());Learning.Profile profile=new Learning.Profile();GlobalCurriculum.chooseCountry(profile,"GB");GlobalCurriculum.choosePack(profile,"england-primary-2021-v1");assertTrue(GlobalCurriculum.pack(profile).inGrade(RomanRead.ID,4));assertFalse(GlobalCurriculum.pack(profile).inGrade(RomanRead.ID,3));}
 @Test public void malformedGivensAndNonNumericResponsesAreRejected(){for(String given:List.of("","IIII","IIX","IC","VX","CC","CI","iv","0","X\nI","Ⅰ")){Question q=RomanRead.make(1);q.prompt=RomanRead.PROMPT+"\n"+given;q.answers=new String[]{"1"};assertNull(RomanRead.read(q));assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of("1")).status);}Question q=RomanRead.make(40);for(String s:List.of("","XL","-40","4e1","40.0","1000"))assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of(s)).status);}
}
